import os
import sqlite3
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('value', '')

    # Validate field name against allowed columns
    allowed_fields = ['username', 'email', 'role']
    if field not in allowed_fields:
        return jsonify({'error': 'Invalid field'}), 400

    # Build query with validated field name but user-supplied value
    query = f"SELECT id, username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'results': results})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user profile by ID."""
    db = get_db()
    cursor = db.execute('SELECT id, username, email, role FROM users WHERE id = ?', (user_id,))
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user account."""
    data = request.get_json()
    if not data or 'username' not in data or 'password' not in data:
        return jsonify({'error': 'Missing fields'}), 400

    password_hash = hashlib.sha256(data['password'].encode()).hexdigest()
    api_key = hashlib.sha256(os.urandom(32)).hexdigest()

    try:
        db = get_db()
        db.execute(
            'INSERT INTO users (username, password_hash, email, role, api_key) VALUES (?, ?, ?, ?, ?)',
            (data['username'], password_hash, data.get('email', ''), 'user', api_key)
        )
        db.commit()
        return jsonify({'status': 'created', 'api_key': api_key}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username exists'}), 409

@app.route('/api/admin/export', methods=['GET'])
def export_data():
    """Export all user data (admin only)."""
    auth_key = request.headers.get('X-Api-Key', '')
    db = get_db()
    cursor = db.execute('SELECT role FROM users WHERE api_key = ?', (auth_key,))
    user = cursor.fetchone()
    if not user or user['role'] != 'admin':
        return jsonify({'error': 'Unauthorized'}), 403

    cursor = db.execute('SELECT id, username, email, role, api_key FROM users')
    results = [dict(row) for row in cursor.fetchall()]
    return jsonify({'users': results})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
